"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["62903"],{49422(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>a,contentTitle:()=>r,toc:()=>h,assets:()=>l});var o=JSON.parse('{"id":"tangfen/keepregulations","title":"","description":"I\'ve actually been lurking all along. At first I only replied to Old Tang\'s posts. But these past couple of days, seeing Miss Chan\'s bad temper and unwillingness to explain further -- while what she said, from a mathematical proof standpoint, was without problems -- for the sake of upholding truth, I had no choice but to step forward and explain her proof on her behalf. Although this would offend many people, I\'m willing to do it.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/keepregulations.md","sourceDirName":"tangfen","slug":"/tangfen/keepregulations","permalink":"/en/tangfen/keepregulations","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"keepregulations","title":"","hide_table_of_contents":true,"sidebar_label":"A small suggestion: on forums, everyone should consciously follow debate norms"},"sidebar":"tangfenSidebar","previous":{"title":"[French Chef], the example you constructed about all finite natural numbers is invalid.","permalink":"/en/tangfen/toflxdcsf6"},"next":{"title":"Let me explain on Ms. Chan\'s behalf why new thoughts under her definition must be new thoughts!","permalink":"/en/tangfen/newthoughts"}}'),s=n(74848),i=n(28453);let a={id:"keepregulations",title:"",hide_table_of_contents:!0,sidebar_label:"A small suggestion: on forums, everyone should consciously follow debate norms"},r="A Small Suggestion of Mine: On the Forum, Everyone Should Consciously Follow Debate Norms",l={},h=[];function d(e){let t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"a-small-suggestion-of-mine-on-the-forum-everyone-should-consciously-follow-debate-norms",children:"A Small Suggestion of Mine: On the Forum, Everyone Should Consciously Follow Debate Norms"})}),"\n",(0,s.jsx)(t.p,{children:"I've actually been lurking all along. At first I only replied to Old Tang's posts. But these past couple of days, seeing Miss Chan's bad temper and unwillingness to explain further -- while what she said, from a mathematical proof standpoint, was without problems -- for the sake of upholding truth, I had no choice but to step forward and explain her proof on her behalf. Although this would offend many people, I'm willing to do it."}),"\n",(0,s.jsx)(t.p,{children:"During this discussion, there appeared a problem common to online debates: instead of discussing the issue itself, people compete on who has more supporters and who posts faster. This is very abnormal. People online vary greatly in level, and truth often has nothing to do with popularity. If the cacophony of voices makes confused people even more confused, then the internet has played a very negative role."}),"\n",(0,s.jsx)(t.p,{children:"I think that in online arguments, if academic issues are involved, academic norms should also be observed. For example, a mathematical proof issue should be discussed using mathematical methods, not by taking things for granted or by being the loudest or having the most people. Also, some people are very dishonest in discussions, frequently falsifying and slandering, then denying things they themselves said and slandering others -- this kind of behavior is inconsistent with the integrity demanded by society today. If such underhanded tactics are used even in virtual arguments, what would happen in reality?"}),"\n",(0,s.jsx)(t.p,{children:"So let me offer some suggestions, casting a brick to attract jade, hoping to improve the atmosphere of online discussions:"}),"\n",(0,s.jsx)(t.p,{children:"First, in discussions, at a minimum, one should quote others' statements in full. A CTRL+C takes care of it now -- it shouldn't be that hard."}),"\n",(0,s.jsx)(t.p,{children:'Second, in discussions, there should be no use of labels like "idiot," and certainly no fabricating stories about who likes whom or what someone is like. What do such things have to do with the discussion?'}),"\n",(0,s.jsx)(t.p,{children:"Third, when making arguments, don't take things for granted. Try to follow academic norms. For example, for mathematical proofs, use mathematical symbols as much as possible and proceed rigorously step by step. Many people now have attended college, and logically speaking, who is right and who is wrong can be easily seen by observers."}),"\n",(0,s.jsx)(t.p,{children:"Fourth, everything should be factual. Don't embellish, and especially don't engage in personal attacks."}),"\n",(0,s.jsx)(t.p,{children:"Fifth, discussions don't necessarily require someone to formally concede defeat, because everyone cares about face. If you demand someone admit their error, most people can't swallow their pride and will just stubbornly hold on and cause trouble, turning any discussion into a farce. For example, this time, I think Miss Chan demanding from the start that Mathematics must admit his error put him in a very difficult position. Miss Chan's proof was correct, but being too aggressive isn't good either -- after all, we're all human, not machines, and everyone has face to consider."}),"\n",(0,s.jsx)(t.p,{children:"Sixth, don't form cliques. Truth has nothing to do with factions. Truth is objective -- it doesn't become true just because more people support it!"})]})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var o=n(96540);let s={},i=o.createContext(s);function a(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);